package wiki

import (
	"encoding/json"
	"fmt"
	"math"
	"path/filepath"
	"sort"
	"strings"

	"pubkey-quest/cmd/server/game/fishing"
	"pubkey-quest/cmd/server/game/gems"
	"pubkey-quest/types"
)

// ── families: generated items on one page ────────────────────────────────────
//
// Fish and gems are generated by size (and gems by quality), hundreds of item
// ids for a few dozen things. The wiki gives each species and gem type one
// page, with its sizes in a table and where to find it; every member id links
// there, and the Items list shows the family as one row.

type family struct {
	page    string // "Items/fish-brook-trout"
	name    string
	image   string
	kind    string // item type, for the Items list
	members []string
	body    func() string
}

// loadFamilies reads fishing.json and gems.json, adds their generated items,
// and groups them.
func (g *gen) loadFamilies() {
	d := g.opt.DataDir
	g.families, g.memberOf = map[string]*family{}, map[string]*family{}
	add := func(f *family) {
		g.families[f.page] = f
		for _, id := range f.members {
			g.memberOf[id] = f
		}
	}
	addItem := func(raw map[string]any) {
		id, _ := raw["id"].(string)
		if g.items[id] != nil {
			return
		}
		var it item
		if b, err := json.Marshal(raw); err == nil && json.Unmarshal(b, &it) == nil {
			g.items[id] = &it
		}
	}

	if cfg, err := fishing.LoadFile(filepath.Join(d, "systems", "fishing.json")); err == nil {
		g.x.fishing = cfg
		for _, raw := range fishing.Items(cfg) {
			addItem(raw)
		}
		for _, sid := range fishing.SortedSpecies(cfg) {
			sp := cfg.Species[sid]
			f := &family{page: "Items/fish-" + sid, name: sp.Name, image: "/res/img/items/fish-" + sid + ".png", kind: "Food"}
			for _, s := range cfg.Sizes {
				f.members = append(f.members, types.FishItemID(sid, s.ID))
			}
			f.members = append(f.members, types.TrophyItemID(sid))
			sid := sid
			f.body = func() string { return g.fishPage(cfg, sid) }
			add(f)
		}
	}

	if cfg, err := gems.LoadFile(filepath.Join(d, "systems", "gems.json")); err == nil {
		g.x.gems = cfg
		for _, raw := range gems.Items(cfg) {
			addItem(raw)
		}
		for _, t := range gems.SortedTypes(cfg) {
			f := &family{page: "Items/gem-" + t, name: cfg.Types[t].Name, image: "/res/img/items/gem-" + t + ".png", kind: "Treasure"}
			for _, s := range cfg.Sizes {
				if !cfg.Types[t].Natural {
					f.members = append(f.members, types.UncutGemID(t, s.ID))
				}
				for _, q := range cfg.Qualities {
					f.members = append(f.members, types.CutGemID(t, s.ID, q.ID))
					for _, p := range types.GemPieces {
						f.members = append(f.members, types.GemPieceID(p, t, s.ID, q.ID))
					}
				}
			}
			t := t
			f.body = func() string { return g.gemPage(cfg, t) }
			add(f)
		}
	}
}

// familyRow is a family's line in the Items list: value and rarity ranges.
func (g *gen) familyRow(f *family) []string {
	lo, hi := math.MaxInt, 0
	var rarities []string
	seen := map[string]bool{}
	for _, id := range f.members {
		it := g.items[id]
		if it == nil {
			continue
		}
		lo, hi = min(lo, it.Value), max(hi, it.Value)
		if !seen[it.Rarity] {
			seen[it.Rarity] = true
			rarities = append(rarities, it.Rarity)
		}
	}
	sort.Slice(rarities, func(i, j int) bool { return rarityRank(rarities[i]) < rarityRank(rarities[j]) })
	rarity := titleCase(rarities[0])
	if len(rarities) > 1 {
		rarity += "–" + titleCase(rarities[len(rarities)-1])
	}
	return []string{g.image(f.image, f.name, 32), link(f.name, f.page), f.kind, rarity,
		fmt.Sprintf("%d–%d gold", lo, hi), "varies"}
}

func rarityRank(r string) int {
	for i, x := range []string{"common", "uncommon", "rare", "very rare", "legendary", "mythic"} {
		if x == r {
			return i
		}
	}
	return 0
}

// memberBullets merges what the reverse indexes say about a family's members.
func (g *gen) memberBullets(b *strings.Builder, f *family) {
	collect := func(idx map[string][]string, render func(string) string) []string {
		var out []string
		seen := map[string]bool{}
		for _, id := range f.members {
			for _, v := range idx[id] {
				line := v
				if render != nil {
					line = render(v)
				}
				if !seen[line] {
					seen[line] = true
					out = append(out, line)
				}
			}
		}
		return out
	}
	bullets(b, "Sold by", collect(g.soldBy, func(n string) string { return g.npcLink(n) + " — " + g.homeLink(g.npcs[n].PrimaryHome) }))
	bullets(b, "Dropped by", collect(g.droppedBy, func(m string) string { return link(g.monsters[m].Name, "Monsters/"+m) }))
	bullets(b, "Found in", collect(g.foundIn, nil))
	bullets(b, "Reward from", collect(g.rewardOf, nil))
	bullets(b, "Given by", collect(g.giftOf, nil))
	bullets(b, "Needed for", collect(g.neededFor, nil))
}

// spotPlace is where a fishing spot is: its town, or the place with a fishing
// node for it.
func (g *gen) spotPlace(spotID string, s types.FishingSpot) string {
	if s.District != "" {
		return g.homeLink(s.District)
	}
	for _, pid := range sortedKeys(g.pois) {
		for _, n := range g.pois[pid].Nodes {
			if n.Spot == spotID {
				return g.poiLink(pid)
			}
		}
	}
	return ""
}

func (g *gen) fishPage(cfg *types.FishingConfig, sid string) string {
	sp := cfg.Species[sid]
	f := g.families["Items/fish-"+sid]
	var b strings.Builder
	if img := g.image(f.image, sp.Name, 96); img != "" {
		b.WriteString(img + "\n\n")
	}
	b.WriteString("_" + sp.Desc + "_\n\n")

	var likes []string
	for _, l := range sp.Likes {
		if bait, ok := cfg.Baits[l]; ok {
			likes = append(likes, bait.Name)
		} else if l == "any" {
			likes = append(likes, "anything")
		}
	}
	bites := map[string]string{"any": "Any time", "day": "By day", "night": "At night", "dawn_dusk": "At dawn and dusk", "dawn": "At dawn"}[sp.Bites]
	how := "Rod and line"
	if sp.Barehand {
		how = "Barehanded only (no hook holds it)"
	}
	facts(&b,
		"Water", titleCase(strings.Join(sp.Water, ", ")),
		"Bites", bites,
		"Caught", how,
		"Takes", strings.Join(likes, ", "),
		"Grows to", num(sp.MaxLb)+" lb",
	)

	var rows [][]string
	for _, s := range cfg.Sizes {
		it := g.items[types.FishItemID(sid, s.ID)]
		if it == nil {
			continue
		}
		rows = append(rows, []string{s.Name, num(it.Weight) + " lb", gold(it.Value), titleCase(it.Rarity)})
	}
	b.WriteString("## Sizes\n\n")
	table(&b, []string{"Size", "Weight", "Value", "Rarity"}, rows)
	b.WriteString("Every fish spoils in 12 hours: cook it, or salt it to keep it a month. Eaten raw, it may give you food poisoning.\n\n")

	var spots []string
	for _, id := range sortedKeys(cfg.Spots) {
		s := cfg.Spots[id]
		if s.Species[sid] <= 0 && s.Barehand[sid] <= 0 {
			continue
		}
		line := s.Name
		if where := g.spotPlace(id, s); strings.Contains(where, "["+s.Name+"|") {
			line = where
		} else if where != "" {
			line += " — " + where
		}
		if s.Barehand[sid] > 0 {
			line += " (barehanded, in the shallows)"
		}
		spots = append(spots, line)
	}
	bullets(&b, "Caught at", spots)

	if t := g.items[types.TrophyItemID(sid)]; t != nil {
		b.WriteString(fmt.Sprintf("**Trophy:** %s will mount a huge one, fresh, as a %s (%s). It never spoils.\n\n",
			g.npcLink("tackle-keeper"), t.Name, gold(t.Value)))
	}
	g.memberBullets(&b, f)
	return b.String()
}

func (g *gen) gemPage(cfg *types.GemsConfig, t string) string {
	gt := cfg.Types[t]
	if gt.Natural {
		return g.pearlPage(cfg, t)
	}
	f := g.families["Items/gem-"+t]
	var b strings.Builder
	imgs := []string{g.image("/res/img/items/gem-"+t+"-uncut.png", "Rough "+gt.Name, 64), g.image(f.image, gt.Name, 64)}
	b.WriteString(strings.TrimSpace(strings.Join(imgs, " ")) + "\n\n")
	b.WriteString("_" + gt.Description + "._\n\n")
	b.WriteString("A gem is found rough. Its quality stays hidden until a jeweller cuts it, so a rough one sells at a standard cut's price. " +
		"Its value is its type's, times its size, times its quality.\n\n")

	head := []string{"Size", "Carats", "Rough"}
	for _, q := range cfg.Qualities {
		head = append(head, q.Name)
	}
	head = append(head, "Cutting fee")
	var rows [][]string
	for _, s := range cfg.Sizes {
		row := []string{s.Name, fmt.Sprintf("%s–%s", num(s.Carats[0]), num(s.Carats[1])), gold(gems.Value(cfg, gems.Gem{Type: t, Size: s.ID}))}
		for _, q := range cfg.Qualities {
			row = append(row, gold(gems.Value(cfg, gems.Gem{Type: t, Size: s.ID, Quality: q.ID})))
		}
		rows = append(rows, append(row, gold(s.CutFee)))
	}
	b.WriteString("## Values\n\n")
	table(&b, head, rows)
	var qual []string
	for _, q := range cfg.Qualities {
		qual = append(qual, fmt.Sprintf("%s %d%%", strings.ToLower(q.Name), int(math.Round(q.DropRate*100))))
	}
	b.WriteString("At the cut: " + strings.Join(qual, ", ") + ".\n\n")

	g.jewelrySection(&b, cfg)

	type face struct {
		tier int
		line string
	}
	var found []face
	for _, pid := range sortedKeys(g.pois) {
		for _, nid := range sortedKeys(g.pois[pid].Nodes) {
			n := g.pois[pid].Nodes[nid]
			if n.Seam == nil || n.Seam.Gems == nil || n.Seam.Gems.Types[t] <= 0 {
				continue
			}
			found = append(found, face{n.Seam.Tier, fmt.Sprintf("%s (tier %d face)", g.poiLink(pid), n.Seam.Tier)})
		}
	}
	sort.SliceStable(found, func(i, j int) bool { return found[i].tier < found[j].tier })
	var faces []string
	for _, fc := range found {
		if !contains(faces, fc.line) {
			faces = append(faces, fc.line)
		}
	}
	bullets(&b, "Rock faces that hold it", faces)
	b.WriteString("Any monster that carries gems can drop one rough: tougher monsters drop more, bigger and rarer ones, and beasts, plants and oozes carry none. A " +
		g.itemLink(types.GeodeID) + " cracked open with a pick may hold one too.\n\n")
	g.memberBullets(&b, f)
	return b.String()
}

// jewelrySection is the jeweller's terms for setting a gem.
func (g *gen) jewelrySection(b *strings.Builder, cfg *types.GemsConfig) {
	j := cfg.Jeweller
	var pieces []string
	for _, p := range types.GemPieces {
		pc := j.Pieces[p]
		pieces = append(pieces, fmt.Sprintf("a %s takes %s", strings.ToLower(pc.Name), gold(pc.Gold)))
	}
	b.WriteString(fmt.Sprintf("## Jewelry\n\n%s cuts rough gems and sets cut ones and pearls in gold: %s, and her work costs %d%% of the gem's value. The piece is worth its gold and its gem together.\n\n",
		g.npcLink(j.NPC), strings.Join(pieces, ", "), int(math.Round(j.Labour*100))))
}

// pearlPage is a natural gem's page: found with its quality, in shellfish.
func (g *gen) pearlPage(cfg *types.GemsConfig, t string) string {
	gt := cfg.Types[t]
	f := g.families["Items/gem-"+t]
	var b strings.Builder
	b.WriteString(strings.TrimSpace(g.image(f.image, gt.Name, 64)) + "\n\n")
	b.WriteString("_" + gt.Description + "._\n\n")
	b.WriteString("A pearl is never cut: it's found as it is, and its quality shows from the start. " +
		"Its value is its type's, times its size, times its quality.\n\n")

	qualName := func(q types.GemQuality) string {
		if q.ID == "standard" {
			return "Standard"
		}
		return q.Name
	}
	head := []string{"Size", "Carats"}
	for _, q := range cfg.Qualities {
		head = append(head, qualName(q))
	}
	var rows [][]string
	for _, s := range cfg.Sizes {
		row := []string{s.Name, fmt.Sprintf("%s–%s", num(s.Carats[0]), num(s.Carats[1]))}
		for _, q := range cfg.Qualities {
			row = append(row, gold(gems.Value(cfg, gems.Gem{Type: t, Size: s.ID, Quality: q.ID})))
		}
		rows = append(rows, row)
	}
	b.WriteString("## Values\n\n")
	table(&b, head, rows)
	var qual []string
	for _, q := range cfg.Qualities {
		qual = append(qual, fmt.Sprintf("%s %d%%", strings.ToLower(qualName(q)), int(math.Round(q.DropRate*100))))
	}
	b.WriteString("As found: " + strings.Join(qual, ", ") + ".\n\n")
	g.jewelrySection(&b, cfg)

	var from []string
	for _, item := range sortedKeys(cfg.Pearls.Shellfish) {
		sf := cfg.Pearls.Shellfish[item]
		total, w := 0, sf.Types[t]
		for _, n := range sf.Types {
			total += n
		}
		if w <= 0 || total == 0 {
			continue
		}
		line := fmt.Sprintf("%s: %s of them hold one", g.itemLink(item), percent(sf.Chance*float64(w)/float64(total)))
		if i := gems.SizeIndex(cfg, sf.MaxSize); i >= 0 {
			line += fmt.Sprintf(", %s at most", strings.ToLower(cfg.Sizes[i].Name))
		}
		from = append(from, line)
	}
	bullets(&b, "Found in", from)
	b.WriteString("Shuck one with a " + g.itemLink("dagger") + " to look inside, or find out when you eat it.\n\n")
	g.memberBullets(&b, f)
	return b.String()
}

// percent writes a chance as a percentage ("6%", "0.6%").
func percent(p float64) string {
	if p >= 0.1 {
		return fmt.Sprintf("%d%%", int(math.Round(p*100)))
	}
	return fmt.Sprintf("%s%%", strings.TrimSuffix(strings.TrimRight(fmt.Sprintf("%.2f", p*100), "0"), "."))
}

func contains(xs []string, s string) bool {
	for _, x := range xs {
		if x == s {
			return true
		}
	}
	return false
}

// gemChance is a monster's chance of a rough gem per kill, or 0.
func (g *gen) gemChance(m *monster) float64 {
	if g.x == nil || g.x.gems == nil {
		return 0
	}
	return gems.KillChance(g.x.gems, &types.MonsterData{Type: m.Type, ChallengeRating: m.CR, GemChance: m.GemChance})
}
